import { copyRow, copyObservation } from './copy.js';
import type { ViewRows } from './validate.js';
import { opaqueIdAt } from '../../contracts/opaque-id.js';
import type { OverviewRows, OwnedRows, DetailRows } from '../generated/galaxy/v1/galaxy_pb.js';
export type Row = OverviewRows['clusters'][number] | OverviewRows['systems'][number] | OverviewRows['connections'][number] | OverviewRows['summaries'][number] | OwnedRows['upserts'][number] | DetailRows['upserts'][number];
export type RowState = { tables: Map<string, Map<string, Row>>; unavailable: string[]; unavailableSummaries: number; ownedCut?: string; observation?: DetailRows['observation'] };
export function emptyRows(): RowState { return { tables: new Map(), unavailable: [], unavailableSummaries: 0 }; }
function key(row: Row): string {
  if ('fleetId' in row) return opaqueIdAt(row.fleetId);
  if ('systemId' in row) return opaqueIdAt(row.systemId);
  if ('clusterId' in row) return opaqueIdAt(row.clusterId);
  return [opaqueIdAt(row.systemA), opaqueIdAt(row.systemB)].sort().join(':');
}
function apply(state: RowState, name: string, upserts: Row[], removals: string[], baseline: boolean, limit: number): void {
  let table = state.tables.get(name); if (!table) { table = new Map(); state.tables.set(name, table); }
  validateChanges(table, upserts, removals, baseline);
  const unavailable = (row: Row | undefined): number => row?.$typeName === 'galaxy.v1.OverviewSystem' && row.observation?.availability !== 1 ? 1 : 0;
  for (const k of removals) {
    if (name === 'summaries') state.unavailableSummaries -= unavailable(table.get(k));
    table.delete(k);
  }
  for (const row of upserts) {
    const k = key(row);
    if (name === 'summaries') state.unavailableSummaries += unavailable(row) - unavailable(table.get(k));
    table.set(k, copyRow(row));
  }
  if (table.size > limit) throw new Error('View retained row budget');
}
function validateChanges(table: Map<string, Row>, upserts: Row[], removals: string[], baseline: boolean): void {
  const seen = new Set(removals);
  if (seen.size !== removals.length || (baseline && removals.length)) throw new Error('Invalid view removals');
  for (const row of upserts) { const k = key(row); if (seen.has(k) || (baseline && table.has(k))) throw new Error('Duplicate view row'); seen.add(k); }

}
export function applyRows(state: RowState, rows: ViewRows, baseline: boolean): void {
  switch (rows.case) {
    case 'overview': applyOverview(state, rows.value, baseline); break;
    case 'owned': applyOwned(state, rows.value, baseline); break;
    case 'detail': applyDetail(state, rows.value, baseline); break;
  }
}
function applyOverview(state: RowState, rows: OverviewRows, baseline: boolean): void {
  apply(state, 'clusters', rows.clusters, rows.removedClusterIds.map(id => opaqueIdAt(id)), baseline, 256);
  apply(state, 'systems', rows.systems, rows.removedSystemIds.map(id => opaqueIdAt(id)), baseline, 4096);
  apply(state, 'connections', rows.connections, rows.removedConnections.map(key), baseline, 16384);
  apply(state, 'summaries', rows.summaries, rows.removedSystemIds.map(id => opaqueIdAt(id)), baseline, 4096);
  removeEdges(state, rows.removedSystemIds);
}
function applyOwned(state: RowState, rows: OwnedRows, baseline: boolean): void {
  apply(state, 'fleets', rows.upserts, rows.removedFleetIds.map(id => opaqueIdAt(id)), baseline, 16384);
  const unavailable = rows.unavailableSourceIds.map(id => opaqueIdAt(id)).sort();
  if (baseline && state.ownedCut !== undefined && unavailable.join() !== state.ownedCut) throw new Error('Snapshot availability changed');
  if (baseline) state.ownedCut = unavailable.join();
  state.unavailable = unavailable;
}
function applyDetail(state: RowState, rows: DetailRows, baseline: boolean): void {
  if (baseline && state.observation && observationKey(state.observation) !== observationKey(rows.observation)) throw new Error('Detail snapshot cut changed');
  apply(state, 'fleets', rows.upserts, rows.removedFleetIds.map(id => opaqueIdAt(id)), baseline, 16384);
  state.observation = copyObservation(rows.observation);
}

function removeEdges(state: RowState, ids: Uint8Array[]): void {
  if (!ids.length) return;
  const removed = new Set(ids.map(id => opaqueIdAt(id)));
  const edges = state.tables.get('connections');
  for (const edge of edges?.keys() ?? []) if (edge.split(':').some(id => removed.has(id))) edges!.delete(edge);
}

function observationKey(o: DetailRows['observation']): string {
  if (!o?.scope) throw new Error('Missing detail observation');
  const s = o.scope;
  return [opaqueIdAt(s.worldId), opaqueIdAt(s.shardId), opaqueIdAt(s.systemId), s.ownerEpoch, s.recoveryGeneration, o.revision, o.committedServerMs, o.availability].join(':');
}

/** Constant-time current availability; sparse summary updates maintain the count. */
export function rowsComplete(state: RowState, slot: number): boolean {
  if (slot === 1) return state.unavailableSummaries === 0;
  if (slot === 2) return state.unavailable.length === 0;
  return state.observation?.availability === 1;
}
