import type { ProjectionWatermark } from '../../../render/remote/projection-state.js';

/** The network's authoritative projection version, independent of GPU apply. */
export type RuleSeedToken = Readonly<{
  connectionGeneration: number;
  watermark: ProjectionWatermark;
}>;

/** Effective values obtained from this seed's source authority. */
export type TransferPolicy = Readonly<{ jumpMs: bigint; cooldownMs: bigint;
  configurationRevision: bigint; modifierRevision: bigint }>;

/** Up to 256 server-proven controllable fleets, or an explicit offline fixture.
 * IDs are fleet/owner/order triples (48 bytes per fleet; zero order means idle).
 * Positions use two XZ pairs (legacy) or two XYZ triples according to positionDimensions.
 * Times are departure/arrival/transfer-ready server ms.
 * Each page is a complete seed for this bounded preview host, never merged
 * with a page from another projection revision. */
export type RuleSeed = Readonly<{
  /** Omitted legacy seeds use XZ; new authority seeds use XYZ. */
  positionDimensions?: 2 | 3;
  transferPolicy?: TransferPolicy;
  movementContext?: MovementContext;
  orbitOffsets?: Uint32Array;
  orbitBytes?: Uint8Array;
  pathOffsets?: Uint32Array;
  pathPoints?: Float64Array;
  token: RuleSeedToken;
  playerId: string;
  ruleVersion: number;
  committedTimeMs: bigint;
  identities: Uint8Array;
  revisions: BigUint64Array;
  positions: Float64Array;
  times: BigUint64Array;
}>;

export type MovementContext = Readonly<{ version: number; catalogId: string; speedPerSecond: number; clearance: number; extent: number; sunClearance: number }>;

export type DomainMode = 'online-preview' | 'offline';
export type MoveInput = Readonly<{
  token: RuleSeedToken;
  fleetId: string;
  orderId: string;
  orbitBody?: number;
  targetX: number;
  targetY?: number;
  targetZ: number;
  nowMs: bigint;
  expectedSystemRevision?: bigint;
  expectedFleetRevision?: bigint;
}>;
export type RuleTopologyToken = Readonly<{ connectionGeneration: number; worldId: string; revision: bigint }>;
/** A complete permitted topology. Index pairs refer to its packed system IDs. */
export type RuleTopology = Readonly<{ token: RuleTopologyToken; systemIds: Uint8Array; edgeIndices: Uint32Array }>;
export type RouteInput = Readonly<{
  token: RuleSeedToken; topology: RuleTopologyToken; fleetId: string; destinationSystemId: string;
  /** Position at the final destination. Intermediate legs arrive at (0,0,0). */
  targetX: number; targetY?: number; targetZ: number; nowMs: bigint; expectedSystemRevision?: bigint;
}>;
export type TransferPreview = Readonly<{
  positionDimensions: 2 | 3;
  /** Source/destination/fleet/owner IDs, 16 bytes each. */
  ids: Uint8Array;
  /** Base/new system revision, command time, departure, arrival, fleet revision. */
  meta: BigUint64Array;
  /** Effective jump, cooldown, configuration/modifier revision, accepted-ready ms. */
  timing: BigUint64Array;
  /** Source and destination, two XZ pairs or XYZ triples in sun-local units. */
  positions: Float64Array;
}>;
export type RoutePreviewResult = Readonly<{
  kind: 'route-preview'; token: RuleSeedToken; topology: RuleTopologyToken; code: number;
  /** Full path including the source. Advisory only; commands commit one leg. */
  path: Uint8Array; totalTravelMs: bigint; arrivalMs: bigint;
  firstLeg: Readonly<{ destinationSystemId: string; targetX: number; targetY?: number; targetZ: number; arrivalMs: bigint }> | null;
  proposal: TransferPreview | null;
}>;
export type RuleChange = Readonly<{
  positionDimensions: 2 | 3;
  token: RuleSeedToken;
  /** Base revision, committed new revision, authoritative/offline command ms. */
  meta: BigUint64Array;
  identities: Uint8Array;
  revisions: BigUint64Array;
  positions: Float64Array;
  times: BigUint64Array;
  orbitOffsets?: Uint32Array;
  orbitBytes?: Uint8Array;
  pathOffsets?: Uint32Array;
  pathPoints?: Float64Array;
  orderIds: Uint8Array;
  /** kind (1 started,2 arrived), departure (0 on arrival), arrival per event. */
  events: BigUint64Array;
}>;
export type PreviewResult = Readonly<{ kind: 'preview'; token: RuleSeedToken; code: number; proposal: RuleChange | null }>;
export type CommitResult = Readonly<{ kind: 'commit'; token: RuleSeedToken; code: number; committed: boolean; nextDeadlineMs: bigint | null }>;
export type DomainStatus = Readonly<{ mode: DomainMode; ruleVersion: number; token: RuleSeedToken | null; fleets: number; nextDeadlineMs: bigint | null }>;
export type DomainBootstrap = Readonly<{ type: 'initialize'; mode: DomainMode; moduleUrl: string; wasmUrl: string }>;
export type DomainRequest =
  | { type: 'seed'; seed: RuleSeed }
  | { type: 'previewMove'; move: MoveInput }
  | { type: 'seedTopology'; topology: RuleTopology }
  | { type: 'previewRoute'; route: RouteInput }
  | { type: 'offlineMove'; move: MoveInput }
  | { type: 'offlineAdvance'; token: RuleSeedToken; nowMs: bigint; limit: number };
export type DomainResult = DomainStatus | PreviewResult | CommitResult | RoutePreviewResult | Readonly<{ kind: 'topology'; token: RuleTopologyToken }>;
export type DomainResponse =
  | { type: 'ready'; status: DomainStatus }
  | { type: 'result'; id: number; result: DomainResult }
  | { type: 'failure'; id?: number; message: string }
  | { type: 'accepted'; change: RuleChange }
  | { type: 'disposed' };
export const MAX_RULE_SEED_FLEETS = 256;
