import {readFleetOrbit,type FleetOrbit} from '../../contracts/fleet-orbit.js';
import { readHullAppearance, type HullAppearance } from '../../contracts/hull-appearance.js';
import { isOpaqueId, opaqueIdAt } from "../../contracts/opaque-id.js";
import { bufferBytes, MAX_SNAPSHOT_BYTES, MAX_SNAPSHOT_ENTITIES, projectionBuffers,
  type ProjectionBatch, type ProjectionScope } from "./contracts.js";

export type RemoteFleet = Readonly<{
  id: string; revision: bigint;
  orbit?: FleetOrbit;
  appearance?: HullAppearance;
  via?: readonly Readonly<{ x: number; y: number; z: number }>[];
  relationship?: 'own' | 'neutral';
  x: number; y: number; z: number; targetX: number; targetY: number; targetZ: number;
  departureMs: bigint; arrivalMs: bigint; moving: boolean;
}>;
export type ProjectionWatermark = {
  scope: ProjectionScope; subscriptionId: string; streamGeneration: bigint;
  sequence: bigint; systemRevision: bigint;
};
export type ProjectionIdentity = Pick<ProjectionScope, "worldId" | "systemId"> & { subscriptionId: string };
export type ProjectionChange = { upserts: readonly RemoteFleet[]; removed: readonly string[] };
export type SnapshotAssembly = {
  id: string; count: number; next: number; bytes: number;
  watermark: ProjectionWatermark; fleets: Map<string, RemoteFleet>;
};

export function copyWatermark(value: ProjectionWatermark): ProjectionWatermark {
  return { ...value, scope: { ...value.scope } };
}

function u64(value: bigint, allowZero = false): boolean {
  return typeof value === "bigint" && value >= (allowZero ? 0n : 1n) && value <= 0xffffffffffffffffn;
}

export function validateProjectionHeader(batch: ProjectionBatch, expected: ProjectionIdentity): void {
  const scope = batch.scope;
  if (!scope || scope.worldId !== expected.worldId || scope.systemId !== expected.systemId
    || batch.subscriptionId !== expected.subscriptionId || !isOpaqueId(scope.shardId)) throw new Error("Projection identity mismatch");
  if (![scope.ownerEpoch, scope.recoveryGeneration, batch.streamGeneration, batch.systemRevision].every(value => u64(value))
    || !u64(batch.sequence, true) || !u64(batch.baseSystemRevision, true)) throw new Error("Invalid projection watermark");
}

export function watermark(batch: ProjectionBatch): ProjectionWatermark {
  return { scope: { ...batch.scope }, subscriptionId: batch.subscriptionId,
    streamGeneration: batch.streamGeneration, sequence: batch.sequence, systemRevision: batch.systemRevision };
}

export function sameScope(a: ProjectionScope, b: ProjectionScope): boolean {
  return a.worldId === b.worldId && a.shardId === b.shardId && a.systemId === b.systemId
    && a.ownerEpoch === b.ownerEpoch && a.recoveryGeneration === b.recoveryGeneration;
}

export function readProjectionChanges(batch: ProjectionBatch): ProjectionChange {
  projectionBuffers(batch);
  const seen = new Set<string>();
  const upserts: RemoteFleet[] = [];
  const removed: string[] = [];
  for (let i = 0; i < batch.revisions.length; i++) {
    const fleet = readFleet(batch, i);
    if (seen.has(fleet.id)) throw new Error("Duplicate projection identity");
    seen.add(fleet.id);
    upserts.push(fleet);
  }
  for (let offset = 0; offset < batch.removedIds.length; offset += 16) {
    const id = opaqueIdAt(batch.removedIds, offset);
    if (seen.has(id)) throw new Error("Duplicate projection identity");
    seen.add(id);
    removed.push(id);
  }
  return { upserts, removed };
}

function readFleet(batch: ProjectionBatch, i: number): RemoteFleet {
  const stride = batch.layoutVersion >= 2 ? 3 : 2, offset = i * stride;
  const row = { id: opaqueIdAt(batch.ids, i * 16), revision: batch.revisions[i]!,
    x: batch.positions[offset]!, y: stride === 3 ? batch.positions[offset + 1]! : 0, z: batch.positions[offset + stride - 1]!,
    targetX: batch.targets[offset]!, targetY: stride === 3 ? batch.targets[offset + 1]! : 0, targetZ: batch.targets[offset + stride - 1]!,
    departureMs: batch.times[i * 2]!, arrivalMs: batch.times[i * 2 + 1]!, moving: (batch.moving[i]! & 1) !== 0 };
  if (!u64(row.revision) || batch.moving[i]! > (batch.layoutVersion >= 4 ? 3 : 1)
    || ![row.x, row.y, row.z, row.targetX, row.targetY, row.targetZ].every(Number.isFinite)) throw new Error("Invalid projection fleet");
  if (row.moving && row.arrivalMs <= row.departureMs) throw new Error("Invalid projection movement interval");
  return presentationMetadata(batch, i, row);
}

function presentationMetadata(batch: ProjectionBatch, i: number, row: RemoteFleet): RemoteFleet {
  if(batch.layoutVersion>=6)row={...row,orbit:readFleetOrbit(batch.orbitBytes!.subarray(batch.orbitOffsets![i],batch.orbitOffsets![i+1]))};
  const appearance = batch.layoutVersion >= 3 ? readHullAppearance(batch.appearance!, i * 7) : undefined;
  if (batch.layoutVersion >= 4) return { ...row, appearance, via: batch.layoutVersion >= 5 ? readPath(batch, i) : undefined, relationship: (batch.moving[i]! & 2) ? 'own' : 'neutral' };
  return appearance ? { ...row, appearance } : row;
}

function readPath(batch: ProjectionBatch, i: number): RemoteFleet['via'] {
  const result: {x: number; y: number; z: number}[] = [];
  for (let j = batch.pathOffsets![i]!; j < batch.pathOffsets![i + 1]!; j++) {
    result.push({ x: batch.pathPoints![j * 3]!, y: batch.pathPoints![j * 3 + 1]!, z: batch.pathPoints![j * 3 + 2]! });
  }
  return result;
}

export function appendSnapshot(current: SnapshotAssembly | null, batch: ProjectionBatch): SnapshotAssembly {
  const chunk = batch.snapshot!;
  validateSnapshotChunk(batch);
  const assembly = current ?? startSnapshot(batch);
  if (!matchesSnapshot(assembly, batch) || assembly.next !== chunk.index) throw new Error("Snapshot chunk does not follow its watermark");
  const change = readProjectionChanges(batch);
  const bytes = bufferBytes(projectionBuffers(batch));
  if (change.removed.length || assembly.fleets.size + change.upserts.length > MAX_SNAPSHOT_ENTITIES
    || assembly.bytes + bytes > MAX_SNAPSHOT_BYTES) throw new Error("Snapshot assembly capacity exceeded");
  for (const fleet of change.upserts) {
    if (assembly.fleets.has(fleet.id)) throw new Error("Duplicate snapshot identity");
    assembly.fleets.set(fleet.id, fleet);
  }
  assembly.bytes += bytes;
  assembly.next++;
  return assembly;
}

function validateSnapshotChunk(batch: ProjectionBatch): void {
  const chunk = batch.snapshot!;
  if (!isOpaqueId(chunk.id) || !Number.isInteger(chunk.count) || chunk.count < 1 || chunk.count > 4096
    || !Number.isInteger(chunk.index) || chunk.index < 0 || chunk.index >= chunk.count) throw new Error("Invalid snapshot chunk");
}

export function matchesSnapshot(assembly: SnapshotAssembly, batch: ProjectionBatch): boolean {
  return assembly.id === batch.snapshot!.id && assembly.count === batch.snapshot!.count
    && assembly.watermark.sequence === batch.sequence && assembly.watermark.systemRevision === batch.systemRevision
    && assembly.watermark.streamGeneration === batch.streamGeneration && sameScope(assembly.watermark.scope, batch.scope);
}

function startSnapshot(batch: ProjectionBatch): SnapshotAssembly {
  if (batch.snapshot!.index !== 0) throw new Error("Snapshot must start at chunk zero");
  return { id: batch.snapshot!.id, count: batch.snapshot!.count, next: 0, bytes: 0,
    watermark: watermark(batch), fleets: new Map() };
}
