import {orbitBuffers} from '../../contracts/fleet-orbit.js';
/** Local projection format. Wire DTOs and GPU storage layouts are independent. */
import type { ServerClockAnchor } from "../../contracts/server-clock.js";
import type { ProjectionTrace } from '../../contracts/causal-context.js';
export type ProjectionScope = {
  worldId: string;
  shardId: string;
  systemId: string;
  ownerEpoch: bigint;
  recoveryGeneration: bigint;
};

export type ProjectionBatch = {
  layoutVersion: 1 | 2 | 3 | 4 | 5 | 6;
  /** Same-port view lifetime, independent of authoritative source revisions. */
  viewGeneration?: number;
  scope: ProjectionScope;
  subscriptionId: string;
  streamGeneration: bigint;
  sequence: bigint;
  baseSystemRevision: bigint;
  systemRevision: bigint;
  /** Same-port metadata removes a dependency on UI welcome-event ordering. */
  clock?: ServerClockAnchor;
  /** Optional selected diagnostic context, never a domain identity or buffer copy. */
  trace?: ProjectionTrace;
  snapshot?: { id: string; index: number; count: number };
  /** UUID bytes, 16 per upsert; slots are allocated only by the renderer. */
  ids: Uint8Array;
  revisions: BigUint64Array;
  /** f64 sun-local XYZ positions/targets in layout 2/3; legacy layout 1 has XZ. */
  positions: Float64Array;
  targets: Float64Array;
  /** Departure/arrival server milliseconds, two per upsert. */
  times: BigUint64Array;
  /** Layout 4 packs movement in bit 0 and server-projected own status in bit 1. */
  moving: Uint8Array;
  removedIds: Uint8Array;
  /** Layout 5: bounded intermediate XYZ vertices, offsets count points per fleet. */
  orbitOffsets?: Uint32Array;
  orbitBytes?: Uint8Array;
  pathOffsets?: Uint32Array;
  pathPoints?: Float64Array;
  /** Layout 3/4: logical ship total + six approved hull counts per upsert. */
  appearance?: Uint32Array;
};

export const MAX_BATCH_ENTITIES = 256;
export const MAX_STREAM_BYTES = 1024 * 1024;
export const MAX_STREAM_BATCHES = 4;
export const MAX_SNAPSHOT_ENTITIES = 16_384;
export const MAX_SNAPSHOT_BYTES = 4 * 1024 * 1024;

/** Structural validation is bounded by a fixed number of views, not entity count. */
export function projectionBuffers(batch: ProjectionBatch): ArrayBuffer[] {
  const count = batch.ids.byteLength / 16;
  const removed = batch.removedIds.byteLength / 16;
  if (![1, 2, 3, 4, 5, 6].includes(batch.layoutVersion) || !Number.isInteger(count) || !Number.isInteger(removed)
    || count + removed > MAX_BATCH_ENTITIES) throw new Error("Invalid projection batch size/layout");
  const views: Array<ArrayBufferView | undefined> = [batch.ids, batch.revisions, batch.positions, batch.targets, batch.times, batch.moving, batch.removedIds];
  const coordinateBytes = count * (batch.layoutVersion >= 2 ? 24 : 16);
  const lengths = [count * 16, count * 8, coordinateBytes, coordinateBytes, count * 16, count, removed * 16];
  const constructors: Array<typeof Uint8Array | typeof BigUint64Array | typeof Float64Array | typeof Uint32Array> = [Uint8Array, BigUint64Array, Float64Array, Float64Array, BigUint64Array, Uint8Array, Uint8Array];
  if (batch.layoutVersion >= 3) {
    views.push(batch.appearance); lengths.push(count * 28); constructors.push(Uint32Array);
  } else if (batch.appearance !== undefined) throw new Error('Appearance requires projection layout 3 or 4');
  if (batch.layoutVersion >= 5) {
    const offsets = batch.pathOffsets, points = batch.pathPoints;
    if (!(offsets instanceof Uint32Array) || offsets.length !== count + 1 || offsets[0] !== 0
      || !(points instanceof Float64Array) || points.length !== offsets[count]! * 3) throw new Error('Invalid projection paths');
    for (let i = 0; i < count; i++) if (offsets[i + 1]! < offsets[i]! || offsets[i + 1]! - offsets[i]! > 14) throw new Error('Projection path exceeds bound');
    if (!points.every(Number.isFinite)) throw new Error('Invalid projection path point');
    views.push(offsets, points); lengths.push((count + 1) * 4, points.byteLength); constructors.push(Uint32Array, Float64Array);
  }
  const buffers = new Set<ArrayBuffer>();
  for (let i = 0; i < views.length; i++) {
    buffers.add(columnBuffer(views[i], constructors[i], lengths[i]));
  }
  if(batch.layoutVersion>=6)for(const buffer of orbitBuffers(count,batch.orbitOffsets,batch.orbitBytes))buffers.add(buffer);
  return [...buffers];
}

export function bufferBytes(buffers: readonly ArrayBuffer[]): number {
  let bytes = 0;
  for (const buffer of buffers) bytes += buffer.byteLength;
  return bytes;
}

function columnBuffer(view: ArrayBufferView | undefined,
  constructor: typeof Uint8Array | typeof BigUint64Array | typeof Float64Array | typeof Uint32Array, length: number): ArrayBuffer {
  if (!view || !(view instanceof constructor) || view.byteLength !== length || !(view.buffer instanceof ArrayBuffer)) throw new Error('Invalid projection column');
  return view.buffer;
}
