import { createNetworkSession } from './session.js';
import type { NetworkControl, NetworkEvent } from './session-contracts.js';
import type { PrepareNetworkServices, NetworkWorkerLifecycle } from './service-contracts.js';
import { createNetworkService } from './service-host.js';
import type { Bus } from '../worker/bus/Bus.js';

/** One socket session, owned by the application broker registration. */
export function createNetworkWorker(bus: Bus) {
  const worker = self as DedicatedWorkerGlobalScope;
  let session: ReturnType<typeof createNetworkSession> | undefined;
  let service: ReturnType<typeof createNetworkService> | undefined;
  let generation = 0; let prepared = false; let failed = false;
  let disconnectStream: (() => void) | undefined;
  const previousError = bus._options.onError;
  function lifecycle(value: NetworkWorkerLifecycle): void { worker.postMessage(value); }
  function fatal(error: unknown): void {
    if (failed) return;
    failed = true; session?.dispose(); disconnectStream?.();
    if (service) void service.dispose().catch(() => {});
    lifecycle({ type: 'networkFatal', generation, message: error instanceof Error ? error.message : String(error) });
  }
  function emit(event: NetworkEvent): void | Promise<void> {
    if (failed) return;
    if (service) {
      try { return service.emit(event); }
      catch (error) { fatal(error); if (event.type === 'pending') return Promise.reject(error); return; }
    }
    throw new Error("Network service is not prepared");
  }
  const busError = (error: { message: string }) => fatal(new Error(error.message));
  bus._options.onError = busError;
  async function prepare(value: PrepareNetworkServices): Promise<void> {
    if (service || !Number.isSafeInteger(value.generation) || value.generation < 1) throw new Error('Invalid network service bootstrap');
    generation = value.generation;
    service = createNetworkService(bus, value.scope, () => {
      if (!session) throw new Error('Network session is not connected'); return session;
    });
    await service.ready();
    if (failed) return;
    prepared = true; lifecycle({ type: 'servicesReady', generation });
  }
  function connect(data: Extract<NetworkControl, { type: 'connect' }>): void {
    if (!prepared || data.generation !== generation) { data.renderPort.close(); throw new Error('Network service bootstrap is not ready'); }
    session?.dispose(); disconnectStream?.(); generation = data.generation;
    try {
      session = createNetworkSession({ bootstrap: data, emit });
      disconnectStream = service?.connectStream(generation);
    } catch (error) { data.renderPort.close(); throw error; }
  }
  function destroy(): void {
    session?.dispose(); session = undefined; disconnectStream?.();
    if (service) void service.dispose().catch(() => {});
    if (bus._options.onError === busError) bus._options.onError = previousError;
    worker.onmessage = null; worker.onmessageerror = null;
  }
  function receive(data: NetworkControl | PrepareNetworkServices): void {
    if (data.type === 'prepareServices') { void prepare(data).catch(fatal); return; }
    if (data.type === 'connect') { connect(data); return; }
    if (data.type === 'dispose') { destroy(); worker.close(); return; }
    if (!session) throw new Error('Network worker has no active session');
    const active = session;
    void active.control(data).catch(error => {
      if (session === active) emit({ type: 'error', message: String(error), requestId: 'requestId' in data ? data.requestId : undefined });
    });
  }
  worker.onmessage = ({ data }) => {
    if (data?.b === true || failed) return;
    try { receive(data); }
    catch (error) { fatal(error); }
  };
  worker.onmessageerror = () => { destroy(); worker.close(); };
  return { destroy };
}
