import { createFrameReader, frameMessage } from './framing.js';
import { SESSION_LIMITS, type NetworkEndpoints } from './session-contracts.js';
import type { FrameTransport } from './transport.js';

export async function connectWebTransport(endpoints: NetworkEndpoints, signal: AbortSignal): Promise<FrameTransport> {
  if (signal.aborted) throw new Error('Network connection aborted');
  const serverCertificateHashes = endpoints.certificateHashes?.map((hash) => ({ algorithm: hash.algorithm, value: new Uint8Array(hash.value) }));
  const session = new WebTransport(endpoints.webTransportUrl!, { serverCertificateHashes });
  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  let writer: WritableStreamDefaultWriter<Uint8Array> | undefined;
  let stopped = false;
  let rejectAbort!: (error: Error) => void;
  const aborted = new Promise<never>((_, reject) => { rejectAbort = reject; });
  // Also observe before racing: close/dispose can arrive at any async seam.
  void aborted.catch(() => {});
  function close(): void {
    if (stopped) return;
    stopped = true;
    signal.removeEventListener('abort', onAbort);
    rejectAbort(new Error('WebTransport connection aborted'));
    if (reader) void reader.cancel().catch(() => {}).finally(() => reader?.releaseLock());
    if (writer) void writer.abort().catch(() => {}).finally(() => writer?.releaseLock());
    session.close();
  }
  function onAbort(): void { close(); }
  signal.addEventListener('abort', onAbort, { once: true });
  const timer = setTimeout(close, SESSION_LIMITS.handshakeMs);
  void session.closed.then(close, close);
  try {
    await Promise.race([session.ready, aborted]);
    const opening = session.createBidirectionalStream().then((stream) => {
      if (stopped) discardStream(stream);
      return stream;
    });
    const stream = await Promise.race([opening, aborted]);
    if (stopped || signal.aborted) { discardStream(stream); throw new Error('WebTransport connection aborted'); }
    reader = stream.readable.getReader(); writer = stream.writable.getWriter();
    return { ...createConnectedTransport(reader, writer, close, () => stopped) };
  } catch (error) { close(); throw error; }
  finally { clearTimeout(timer); }
}

function discardStream(stream: WebTransportBidirectionalStream): void {
  void stream.readable.cancel().catch(() => {});
  void stream.writable.abort().catch(() => {});
}

function createConnectedTransport(reader: ReadableStreamDefaultReader<Uint8Array>, writer: WritableStreamDefaultWriter<Uint8Array>, close: () => void, stopped: () => boolean): FrameTransport {
  const framing = createFrameReader(reader, SESSION_LIMITS.readBytes);
  let queuedBytes = 0;
  let queuedFrames = 0;
  let tail = Promise.resolve();
  return {
    kind: 'webtransport', receive: framing.receive, close,
    send(payload): Promise<void> {
      if (stopped()) return Promise.reject(new Error('WebTransport is closed'));
      const frame = frameMessage(payload);
      if (queuedBytes + frame.byteLength > SESSION_LIMITS.sendBytes || queuedFrames >= SESSION_LIMITS.sendFrames) return Promise.reject(new Error('WebTransport send budget exceeded'));
      queuedBytes += frame.byteLength; queuedFrames++;
      const sending = tail.then(async () => {
        if (stopped()) throw new Error('WebTransport is closed');
        await writer.ready;
        await writer.write(frame);
      }).finally(() => { queuedBytes -= frame.byteLength; queuedFrames--; });
      tail = sending.catch(() => { close(); });
      return sending;
    },
  };
}
