import type { CommandKey, MoveCommand, MoveReceipt, TransferCommand } from './generated/galaxy/v1/galaxy_pb.js';
export type PlayerCommand = MoveCommand | TransferCommand;
import type { ServerClockAnchor } from '../contracts/server-clock.js';
import type { WorldTopologyView } from '../contracts/world-topology.js';
import type { ProjectionWatermark } from '../render/remote/projection-state.js';
import type { CausalContext } from '../worker/protocol/services.js';
import type { StrategicFrontier, StrategicInterest } from './strategic-contracts.js';
import { MAX_MESSAGE_BYTES } from './limits.js';
export type { ServerClockAnchor as ClockAnchor } from '../contracts/server-clock.js';

export type NetworkEndpoints = {
  webTransportUrl?: string;
  webSocketUrl: string;
  /** Explicit loopback fixture pins only; never a production trust bypass. */
  certificateHashes?: { algorithm: 'sha-256'; value: Uint8Array }[];
};
export type SystemSubscription = { worldId: string; systemId: string; subscriptionId: string };
export type NetworkBootstrap = {
  type: 'connect'; generation: number; endpoints: NetworkEndpoints;
  credential: Uint8Array; renderPort: MessagePort; gameplayPort?:MessagePort;
  playerViews?: {worldId?: string; playerId?: string; viewportNavigation?: boolean};
  viewInterests?: import('./views/interests.js').ViewInterests;
} & ({ subscription: SystemSubscription; discovery?: never }
  | { discovery: { subscriptionId: string; preferredSystemId?: string }; subscription?: never });
export type NetworkControl = NetworkBootstrap
  | { type: 'move'; requestId: string; commandId: string; fleetId: string;
      target: { x: number; y?: number; z: number }; orbitBody?: number; expectedSystemRevision?: bigint; expectedFleetRevision?: bigint; context?: CausalContext }
  | { type: 'transfer'; requestId: string; commandId: string; fleetId: string; destinationSystemId: string;
      target: { x: number; y?: number; z: number }; expectedSystemRevision?: bigint; context?: CausalContext }
  | { type: 'retry'; requestId: string; command: PlayerCommand; context?: CausalContext }
  | { type: 'queryReceipt'; requestId: string; key: CommandKey; context?: CausalContext }
  | { type: 'strategicInterest'; interest: StrategicInterest }
  | { type: 'disconnect' } | { type: 'dispose' };

export type NetworkEvent =
  | {type:'viewInterests';generation:number;interests:import('./views/interests.js').ViewInterests}
  | { type: 'viewChanged'; status: import('./views/service-contracts.js').PlayerViewStatus }
  | { type: 'viewBarrier'; generation: number; epoch: bigint }

  | { type: 'strategic'; frontier: StrategicFrontier }
  | { type: 'state'; generation: number; state: 'connecting' | 'ready' | 'closed'; transport?: 'webtransport' | 'websocket' }
  | { type: 'welcome'; generation: number; playerId: string; worldId: string; connectionGeneration: bigint; clock: ServerClockAnchor; contentEndpoint?: string }
  | { type: 'topology'; generation: number; topology: WorldTopologyView; subscription: SystemSubscription; viewToken: import('./views/service-contracts.js').PlayerViewToken }
  | { type: 'pending'; requestId: string; command: PlayerCommand }
  | { type: 'receipt'; receipt: MoveReceipt }
  | { type: 'unknown'; requestId: string; key: CommandKey }
  | { type: 'received'; streamGeneration: bigint; sequence: bigint; systemRevision: bigint; snapshotComplete: boolean; watermark: ProjectionWatermark }
  | { type: 'resync'; reason: string }
  | { type: 'error'; message: string; requestId?: string };

export const SESSION_LIMITS = {
  readBytes: MAX_MESSAGE_BYTES * 4, readFrames: 16, sendBytes: 1024 * 1024, sendFrames: 32,
  pendingProjectionBytes: 1024 * 1024, pendingProjectionBatches: 64,
  pendingCommands: 128, handshakeMs: 5000, receiptMs: 10000, snapshotMs: 5000,
} as const;
